import{d as e,k as t,m as n,t as r}from"./chunks/plugin-vue_export-helper.sM-KdTqA.js";const i=JSON.parse(`{"title":"原生权限配置、真机调试与打包发布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-and-publish.md","filePath":"guide/native-and-publish.md"}`);var a={name:`guide/native-and-publish.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h1 id="原生权限配置、真机调试与打包发布" tabindex="-1">原生权限配置、真机调试与打包发布 <a class="header-anchor" href="#原生权限配置、真机调试与打包发布" aria-label="Permalink to “原生权限配置、真机调试与打包发布”">​</a></h1><p>当你的应用页面与交互逻辑开发完成后，你可以通过 QC Flutter Flow 内置的 <strong>「原生配置中枢」</strong> 与 <strong>「离线优先构建沙盒」</strong>，无需手工编写复杂的各端原生配置文件，即可完成权限配置、签名打包与多端发布。</p><hr><h2 id="一、项目原生配置中枢" tabindex="-1">一、项目原生配置中枢 <a class="header-anchor" href="#一、项目原生配置中枢" aria-label="Permalink to “一、项目原生配置中枢”">​</a></h2><p>点击画布顶部工具栏右上角的 <strong>「项目原生配置」</strong> 按钮，即可在一个弹窗中统一管理 <strong>Android、iOS 与 macOS</strong> 各端的工程配置：</p><h3 id="_1-基础应用信息" tabindex="-1">1. 基础应用信息 <a class="header-anchor" href="#_1-基础应用信息" aria-label="Permalink to “1. 基础应用信息”">​</a></h3><ul><li><strong>应用显示名称 (App Name)</strong>：安装在手机桌面或电脑窗口顶部显示的名称。</li><li><strong>应用包名 (Package Name / Bundle ID)</strong>：如 <code>com.company.myapp</code>，自动同步到 Android 与 iOS 工程。</li><li><strong>版本号 (Version Name &amp; Build Number)</strong>：如 <code>1.0.0+1</code>。</li></ul><h3 id="_2-组件权限智能感知与一键添加" tabindex="-1">2. 组件权限智能感知与一键添加 <a class="header-anchor" href="#_2-组件权限智能感知与一键添加" aria-label="Permalink to “2. 组件权限智能感知与一键添加”">​</a></h3><p>很多新手在打包手机 App 时最头疼的就是“加了扫码或定位组件，结果真机运行闪退，因为忘了配 Android 权限或 iOS 隐私说明文案”。</p><p>在 QC Flutter Flow 中，系统会<strong>自动扫描你当前画布上用到的所有组件</strong>，并列出推荐的原生权限清单：</p><table tabindex="0"><thead><tr><th style="text-align:left;">当你在画布中使用了...</th><th style="text-align:left;">系统自动识别并推荐添加的 Android 权限</th><th style="text-align:left;">系统自动生成的 iOS 隐私描述 (<code>Info.plist</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>条码/二维码扫描 (<code>BarcodeScanner</code>)</strong></td><td style="text-align:left;"><code>CAMERA</code>、<code>FLASHLIGHT</code></td><td style="text-align:left;"><code>NSCameraUsageDescription</code>（用于扫描条形码与二维码）</td></tr><tr><td style="text-align:left;"><strong>地图/定位组件</strong></td><td style="text-align:left;"><code>ACCESS_FINE_LOCATION</code>、<code>ACCESS_COARSE_LOCATION</code></td><td style="text-align:left;"><code>NSLocationWhenInUseUsageDescription</code>（用于展示地图与定位）</td></tr><tr><td style="text-align:left;"><strong>手写签名板 (<code>SignaturePad</code>) / 文件上传 (<code>Uploader</code>)</strong></td><td style="text-align:left;">存储与媒体读取权限</td><td style="text-align:left;"><code>NSPhotoLibraryAddUsageDescription</code>（用于保存或选择相册图片）</td></tr></tbody></table><p><strong>操作方式</strong>：</p><ol><li>打开「权限管理」标签页，查看顶部高亮的 <strong>「组件自动推荐权限列表」</strong>。</li><li>点击 <strong>「一键添加推荐权限」</strong>，也可根据需要手动勾选添加网络、麦克风、蓝牙、通知等其它权限。</li></ol><h3 id="_3-第三方-sdk-密钥管理" tabindex="-1">3. 第三方 SDK 密钥管理 <a class="header-anchor" href="#_3-第三方-sdk-密钥管理" aria-label="Permalink to “3. 第三方 SDK 密钥管理”">​</a></h3><p>如果项目中使用了地图、支付或推送服务，可在 <strong>「第三方密钥」</strong> 标签页直接填入对应的 Android / iOS API Key，系统会自动注入到各端原生配置中。</p><h3 id="_4-变更对比预览-diff-与安全落盘" tabindex="-1">4. 变更对比预览（Diff）与安全落盘 <a class="header-anchor" href="#_4-变更对比预览-diff-与安全落盘" aria-label="Permalink to “4. 变更对比预览（Diff）与安全落盘”">​</a></h3><p>点击 <strong>「保存与应用」</strong> 前，系统会弹出 <strong>「变更对比预览 (Unified Diff)」</strong> 窗口：</p><ul><li>用<strong>绿色高亮</strong>展示将在 <code>AndroidManifest.xml</code>、<code>build.gradle</code>、<code>Info.plist</code> 等文件中新增的配置行；</li><li>确认无误后点击 <strong>「确认应用」</strong>，才会原子化安全写入磁盘，杜绝误改破坏工程。</li></ul><hr><h2 id="二、android-签名证书一键生成" tabindex="-1">二、Android 签名证书一键生成 <a class="header-anchor" href="#二、android-签名证书一键生成" aria-label="Permalink to “二、Android 签名证书一键生成”">​</a></h2><p>发布正式版 Android 安装包（APK / AAB）需要签名证书（<code>.jks</code>）。你不需要打开终端去敲复杂的 <code>keytool</code> 命令：</p><ol><li>在「项目原生配置」中切换到 <strong>「签名配置」</strong>（或点击构建菜单中的「APK 签名工具」）。</li><li>选择 <strong>「生成全新 Keystore 证书」</strong>，依次填入： <ul><li><strong>证书文件名</strong>（默认 <code>release.jks</code>）</li><li><strong>密钥别名 (Key Alias)</strong></li><li><strong>密钥库密码与别名密码</strong></li><li><strong>开发者/组织名称与有效期（年）</strong></li></ul></li><li>点击 <strong>「一键生成并绑定」</strong>，系统会自动生成证书文件，并将签名配置自动写入 Android 构建脚本中。</li></ol><hr><h2 id="三、真机调试与秒级热重载" tabindex="-1">三、真机调试与秒级热重载 <a class="header-anchor" href="#三、真机调试与秒级热重载" aria-label="Permalink to “三、真机调试与秒级热重载”">​</a></h2><ol><li><strong>连接设备</strong>： <ul><li><strong>桌面端调试</strong>：直接选择 <code>Windows</code> 或 <code>macOS</code> 桌面设备，最快验证业务逻辑。</li><li><strong>手机真机调试</strong>：用数据线连接开启了「USB 调试」的 Android 手机（或 iOS 设备），顶部设备下拉框会自动识别并列出你的手机型号。</li><li><strong>模拟器调试</strong>：点击设备下拉框旁的「新建/启动模拟器」，可直接创建或拉起本地模拟器。</li></ul></li><li><strong>一键运行（离线优先加速）</strong>： <ul><li>点击顶部绿色 <strong>「▶ 运行」</strong> 按钮。</li><li>平台优先采用本地离线依赖缓存（<code>--offline</code>），相比传统每次联网检查依赖提速 <strong>80% 以上</strong>；同时自动继承系统网络代理并设置 10 分钟超时护栏，防止进程卡死。</li></ul></li><li><strong>实时日志与热重载</strong>： <ul><li>在底部 <strong>「运行日志」</strong> 面板查看应用输出与调试日志（配合 <code>系统_调试输出()</code> 或 <code>系统_打印日志()</code> 使用）。</li><li>修改画布样式或代码后，点击 <strong>「⚡ 热重载」</strong> 即可在 1 秒内刷新真机画面；点击 <strong>「⏹ 终止运行」</strong> 会彻底清理所有后台构建子进程，不留僵尸进程占用端口。</li></ul></li></ol><hr><h2 id="四、打包导出多端安装包与纯净源码" tabindex="-1">四、打包导出多端安装包与纯净源码 <a class="header-anchor" href="#四、打包导出多端安装包与纯净源码" aria-label="Permalink to “四、打包导出多端安装包与纯净源码”">​</a></h2><p>点击顶部工具栏的 <strong>「构建发布」</strong>，你可以选择两种交付形态：</p><ol><li><strong>直接导出各平台安装包</strong>： <ul><li><strong>Android</strong>：导出已签名的 <code>.apk</code> 安装包或上架 Google Play 的 <code>.aab</code> 包。</li><li><strong>iOS</strong>：导出 iOS 工程与 <code>.ipa</code> 归档包（需在 macOS 环境下配合 Xcode 签名）。</li><li><strong>桌面端与 Web</strong>：一键打包生成 Windows 可执行程序、macOS <code>.app</code> 应用或 Web 静态站点。</li></ul></li><li><strong>导出 100% 纯净标准 Flutter 源码工程</strong>： <ul><li>平台生成的所有页面、路由、主题配置与控制器均为<strong>标准、可读性极高的原生 Dart / Flutter 源码</strong>，无任何专有黑盒锁定。</li><li>你可以随时将完整工程目录复制到 VS Code 或 Android Studio 中进行二次深度开发或接入企业现有 CI/CD 流水线。</li></ul></li></ol>`,29)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};